step.script:
env HOME=/tmp bash -lc 'set -eu; if [ -z "" ]; then
  echo "BUNNY_PULL_ZONE_ID is not set, skipping cache purge";
  exit 0;
fi; echo "Purging BunnyCDN cache for pull zone ..."; HTTP_STATUS=$(docker run --rm curlimages/curl:latest -s -o /dev/null -w "%{http_code}" -X POST "https://api.bunny.net/pullzone//purgeCache" -H "AccessKey: " -H "Content-Type: application/json"); echo "HTTP status: $HTTP_STATUS"; if [ "$HTTP_STATUS" != "204" ]; then
  echo "Cache purge failed with HTTP status $HTTP_STATUS";
  exit 1;
fi; echo "Cache purged successfully"'
